package main

import (
	"errors"
	"fmt"
)

// divide returns a result and an error; the error is the LAST return value by convention.
func divide(a, b float64) (float64, error) {
	if b == 0 {
		// errors.New: a simple, static message.
		return 0, errors.New("division by zero")
	}
	return a / b, nil // nil error signals success
}

// parseAge wraps a lower-level error with context using fmt.Errorf and %w.
func parseAge(raw string, n int) (int, error) {
	if n < 0 {
		// fmt.Errorf: dynamic message; %w would wrap, %v just formats.
		return 0, fmt.Errorf("parseAge %q: negative value %d", raw, n)
	}
	return n, nil
}

func main() {
	// Happy path: err is nil, use the result.
	if q, err := divide(10, 2); err != nil {
		fmt.Println("error:", err)
	} else {
		fmt.Println("10 / 2 =", q)
	}

	// Failure path: check err first, do not trust the result on error.
	if _, err := divide(1, 0); err != nil {
		fmt.Println("error:", err) // prints the message from Error()
	}

	if _, err := parseAge("-3", -3); err != nil {
		fmt.Println("error:", err)
	}
}

package main

import (
	"errors"
	"fmt"
)

// Sentinel error: an exported, comparable value (named ErrXxx).
var ErrNotFound = errors.New("record not found")

// Custom error type carrying structured data (named XxxError).
type ValidationError struct {
	Field string
	Msg   string
}

func (e *ValidationError) Error() string {
	return fmt.Sprintf("validation: field %q %s", e.Field, e.Msg)
}

func lookup(id int) error {
	if id == 0 {
		return &ValidationError{Field: "id", Msg: "must be non-zero"}
	}
	if id == 42 {
		return ErrNotFound // return the sentinel directly
	}
	return nil
}

// service wraps lookup's error with context using %w, preserving the chain.
func service(id int) error {
	if err := lookup(id); err != nil {
		return fmt.Errorf("service.lookup(id=%d): %w", id, err)
	}
	return nil
}

func main() {
	err := service(42)
	fmt.Println("chain:", err)
	// errors.Is walks the chain and matches the sentinel even though it is wrapped.
	if errors.Is(err, ErrNotFound) {
		fmt.Println("-> handled as NOT FOUND (404)")
	}

	err = service(0)
	fmt.Println("chain:", err)
	// errors.As extracts the concrete *ValidationError from inside the chain.
	var ve *ValidationError
	if errors.As(err, &ve) {
		fmt.Printf("-> handled as BAD REQUEST (400), field=%s\n", ve.Field)
	}
}

package main

import "fmt"

type MyError struct{ Code int }

func (e *MyError) Error() string { return fmt.Sprintf("code %d", e.Code) }

// BAD: returns a *MyError that is nil, but as an interface it is NOT nil.
func doBad(fail bool) error {
	var e *MyError // typed nil pointer
	if fail {
		e = &MyError{Code: 500}
	}
	return e // even when e is nil, the returned interface carries type *MyError
}

// GOOD: return the untyped nil literal on the success path.
func doGood(fail bool) error {
	if fail {
		return &MyError{Code: 500}
	}
	return nil // a true nil interface (no type, no value)
}

func main() {
	if err := doBad(false); err != nil {
		// This branch RUNS even though nothing failed!
		fmt.Printf("doBad reports error: %v (type %T)\n", err, err)
	} else {
		fmt.Println("doBad: no error")
	}

	if err := doGood(false); err != nil {
		fmt.Println("doGood reports error:", err)
	} else {
		fmt.Println("doGood: no error")
	}
}
